import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { Slot } from "expo-router";
import { StatusBar } from "expo-status-bar";
import { useState } from "react";

import {
  ApiClientProvider,
  createApiClient,
  defaultBaseUrl,
} from "../api/ApiClientProvider";
import { PhoneFrame } from "../components/PhoneFrame";
import { FontGate } from "../theme/FontGate";
import { ThemeProvider, useTheme } from "../theme/ThemeProvider";

// A barra de status segue o tema do app, que pode diferir do tema do aparelho.
function ThemedStatusBar() {
  const { name } = useTheme();
  return <StatusBar style={name === "escuro" ? "light" : "dark"} />;
}

export default function RootLayout() {
  const [queryClient] = useState(() => new QueryClient());
  const [apiClient] = useState(() => createApiClient(defaultBaseUrl()));

  return (
    <QueryClientProvider client={queryClient}>
      <ApiClientProvider client={apiClient}>
        <ThemeProvider>
          <PhoneFrame>
            <FontGate>
              <Slot />
            </FontGate>
          </PhoneFrame>
          <ThemedStatusBar />
        </ThemeProvider>
      </ApiClientProvider>
    </QueryClientProvider>
  );
}
import { ApiStatusScreen } from "../status/ApiStatusScreen";

export default ApiStatusScreen;
import { Redirect } from "expo-router";
import type { ComponentType } from "react";

// Só em desenvolvimento. Com o `require` atrás do __DEV__, a vitrine nem entra no bundle de
// produção, e a rota volta para o início.
const VitrineScreen: ComponentType | null = __DEV__
  ? // eslint-disable-next-line @typescript-eslint/no-require-imports
    require("../vitrine/VitrineScreen").VitrineScreen
  : null;

export default function VitrineRoute() {
  return VitrineScreen ? <VitrineScreen /> : <Redirect href="/" />;
}
import { createApiClient, type ApiClient } from "@maxx/api-client";
import { createContext, useContext, type ReactNode } from "react";
import { Platform } from "react-native";

// Origem única (ADR 0001): na web a API está no mesmo host, sob /api. No nativo, a URL
// pública vem de EXPO_PUBLIC_API_URL, que não é segredo e vai para o binário.
export function defaultBaseUrl(): string {
  return Platform.OS === "web" ? "" : (process.env.EXPO_PUBLIC_API_URL ?? "");
}

const ApiClientContext = createContext<ApiClient | null>(null);

export function ApiClientProvider({
  client,
  children,
}: {
  client: ApiClient;
  children: ReactNode;
}) {
  return (
    <ApiClientContext.Provider value={client}>
      {children}
    </ApiClientContext.Provider>
  );
}

export function useApiClient(): ApiClient {
  const client = useContext(ApiClientContext);
  if (!client) {
    throw new Error("useApiClient fora do ApiClientProvider.");
  }
  return client;
}

export { createApiClient };
import { useQuery } from "@tanstack/react-query";

import { useApiClient } from "./ApiClientProvider";

export type HealthResult = { httpStatus: number; status: string };

export function useHealth() {
  const client = useApiClient();

  return useQuery({
    queryKey: ["health"],
    queryFn: async (): Promise<HealthResult> => {
      const { data, response } = await client.GET("/api/health");
      if (!response.ok || !data) {
        throw new Error(`GET /api/health respondeu ${response.status}.`);
      }
      return { httpStatus: response.status, status: data.status };
    },
  });
}
import { useState } from "react";
import {
  Pressable,
  StyleSheet,
  Text,
  TextInput,
  View,
  type TextInputProps,
} from "react-native";

import { fontFamily } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { interacao, raios, tamanhos } from "../theme/tokens";
import { focusRingStyle, noOutline, useFocusRing } from "./focusRing";
import { Icon } from "./Icon";

interface TextFieldProps extends Omit<
  TextInputProps,
  "style" | "editable" | "secureTextEntry" | "placeholderTextColor"
> {
  label: string;
  // Esconde o texto e oferece o botão de mostrar.
  password?: boolean;
  disabled?: boolean;
}

const RECUO = 14;

export function TextField({
  label,
  password = false,
  disabled = false,
  onFocus,
  onBlur,
  ...input
}: TextFieldProps) {
  const { colors } = useTheme();
  const [focused, setFocused] = useState(false);
  const [revealed, setRevealed] = useState(false);
  const borda = focused ? interacao.bordaDeCampoEmFoco : interacao.bordaDeCampo;

  return (
    <View style={styles.coluna}>
      <Text style={[styles.rotulo, { color: colors.ink }]}>{label}</Text>
      <View
        testID="campo-caixa"
        style={[
          styles.caixa,
          {
            borderWidth: borda,
            borderColor: focused ? colors.focus : colors.fieldLine,
            backgroundColor: disabled ? colors.surface2 : colors.fieldBg,
            // A borda mais grossa do foco não pode empurrar o texto.
            paddingLeft: RECUO - borda,
          },
        ]}
      >
        <TextInput
          autoCapitalize={password ? "none" : undefined}
          autoCorrect={password ? false : undefined}
          {...input}
          aria-label={label}
          editable={!disabled}
          secureTextEntry={password && !revealed}
          placeholderTextColor={colors.ink3}
          onFocus={(event) => {
            setFocused(true);
            onFocus?.(event);
          }}
          onBlur={(event) => {
            setFocused(false);
            onBlur?.(event);
          }}
          style={[
            styles.entrada,
            noOutline,
            { color: disabled ? colors.ink3 : colors.ink },
          ]}
        />
        {password && (
          <RevealButton
            revealed={revealed}
            disabled={disabled}
            onPress={() => setRevealed((atual) => !atual)}
          />
        )}
      </View>
    </View>
  );
}

function RevealButton({
  revealed,
  disabled,
  onPress,
}: {
  revealed: boolean;
  disabled: boolean;
  onPress: () => void;
}) {
  const { colors } = useTheme();
  const { focusVisible, focusProps } = useFocusRing();

  return (
    <Pressable
      role="button"
      aria-label={revealed ? "Ocultar senha" : "Mostrar senha"}
      disabled={disabled}
      onPress={onPress}
      {...focusProps}
      style={({ pressed }) => [
        styles.mostrar,
        noOutline,
        pressed && { opacity: interacao.opacidadePressionado },
        focusVisible && focusRingStyle(colors.focus),
      ]}
    >
      <Icon
        name={revealed ? "eyeOff" : "eye"}
        color={disabled ? colors.ink3 : colors.ink2}
      />
    </Pressable>
  );
}

const styles = StyleSheet.create({
  coluna: { gap: 8 },
  rotulo: {
    fontFamily: fontFamily({ familia: "Instrument Sans", peso: 600 }),
    fontSize: 14,
    lineHeight: 20,
  },
  caixa: {
    height: tamanhos.campo,
    borderRadius: raios.campos,
    flexDirection: "row",
    alignItems: "center",
  },
  // 16 fora da escala: abaixo disso, o Safari do iPhone dá zoom na tela ao focar o campo.
  entrada: {
    flex: 1,
    height: "100%",
    paddingVertical: 0,
    paddingHorizontal: 0,
    paddingRight: RECUO,
    fontFamily: fontFamily({ familia: "Instrument Sans", peso: 400 }),
    fontSize: 16,
  },
  mostrar: {
    width: tamanhos.alvoDeToque,
    height: tamanhos.alvoDeToque,
    borderRadius: raios.campos,
    alignItems: "center",
    justifyContent: "center",
  },
});
import { Pressable, StyleSheet, Text, View } from "react-native";

import { fontFamily } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { interacao, raios, tamanhos } from "../theme/tokens";
import { focusRingStyle, noOutline, useFocusRing } from "./focusRing";

interface SegmentedControlProps<T extends string> {
  // Nome do grupo para o leitor de tela.
  label: string;
  options: readonly { value: T; label: string }[];
  value: T;
  onChange: (value: T) => void;
  disabled?: boolean;
}

const RESPIRO_DO_TRILHO = 4;
const BORDA_DO_TRILHO = 1;

export function SegmentedControl<T extends string>({
  label,
  options,
  value,
  onChange,
  disabled = false,
}: SegmentedControlProps<T>) {
  const { colors } = useTheme();

  return (
    <View
      role="radiogroup"
      aria-label={label}
      testID="segmentado-trilho"
      style={[
        styles.trilho,
        {
          backgroundColor: disabled ? colors.surface2 : colors.surface,
          borderColor: colors.line,
        },
      ]}
    >
      {options.map((option) => (
        <Segment
          key={option.value}
          label={option.label}
          selected={option.value === value}
          disabled={disabled}
          onPress={() => onChange(option.value)}
        />
      ))}
    </View>
  );
}

function Segment({
  label,
  selected,
  disabled,
  onPress,
}: {
  label: string;
  selected: boolean;
  disabled: boolean;
  onPress: () => void;
}) {
  const { name, colors } = useTheme();
  const { focusVisible, focusProps } = useFocusRing();

  return (
    <Pressable
      role="radio"
      aria-checked={selected}
      aria-label={label}
      disabled={disabled}
      onPress={onPress}
      {...focusProps}
      style={({ pressed }) => [
        styles.segmento,
        noOutline,
        selected && { backgroundColor: colors.segmentOn },
        // A única sombra da interface: controle segmentado, só no claro.
        selected &&
          !disabled &&
          name === "claro" && { boxShadow: colors.segmentShadow },
        pressed && { opacity: interacao.opacidadePressionado },
        focusVisible && focusRingStyle(colors.focus),
      ]}
    >
      <Text
        numberOfLines={1}
        style={[
          styles.texto,
          {
            color: disabled ? colors.ink3 : selected ? colors.ink : colors.ink2,
          },
        ]}
      >
        {label}
      </Text>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  trilho: {
    flexDirection: "row",
    borderRadius: raios.controleSegmentado,
    borderWidth: BORDA_DO_TRILHO,
    padding: RESPIRO_DO_TRILHO,
  },
  // Com o respiro e a borda do trilho, cada segmento chega aos 44 de toque.
  segmento: {
    flex: 1,
    minHeight: tamanhos.alvoDeToque - 2 * (RESPIRO_DO_TRILHO + BORDA_DO_TRILHO),
    paddingHorizontal: 12,
    alignItems: "center",
    justifyContent: "center",
    borderRadius: raios.segmentoAtivo,
  },
  texto: {
    fontFamily: fontFamily({ familia: "Instrument Sans", peso: 600 }),
    fontSize: tamanhos.botaoDiscreto.texto,
  },
});
import type { ReactNode } from "react";
import { ScrollView, StyleSheet, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { espacamento } from "../theme/tokens";

interface ScreenProps {
  children: ReactNode;
  // Conteúdo maior que a tela. Sem isso, a tela ocupa a altura disponível, sem rolar.
  scroll?: boolean;
  // Acima da navegação inferior, que já cuida da área segura de baixo.
  aboveNav?: boolean;
}

// O espaço de toda tela: margem lateral de 16, área segura do aparelho e 24 de respiro no fim.
export function Screen({
  children,
  scroll = false,
  aboveNav = false,
}: ScreenProps) {
  const insets = useSafeAreaInsets();
  const padding = {
    paddingTop: insets.top,
    paddingBottom:
      espacamento.respiroAntesDaNavegacao + (aboveNav ? 0 : insets.bottom),
    paddingLeft: espacamento.margemLateral + insets.left,
    paddingRight: espacamento.margemLateral + insets.right,
  };

  if (scroll) {
    return (
      <ScrollView
        testID="tela"
        style={styles.fill}
        contentContainerStyle={padding}
      >
        {children}
      </ScrollView>
    );
  }

  return (
    <View testID="tela" style={[styles.fill, padding]}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  fill: { flex: 1 },
});
import { Pressable, StyleSheet, Text, View } from "react-native";

import { fontFamily } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { interacao, raios, tamanhos } from "../theme/tokens";
import { focusRingStyle, noOutline, useFocusRing } from "./focusRing";

interface ButtonProps {
  label: string;
  onPress: () => void;
  variant?: "primary" | "secondary";
  // `large` é só o Entrar do login. O discreto ocupa a largura que o pai der.
  size?: "compact" | "large";
  disabled?: boolean;
}

export function Button({
  label,
  onPress,
  variant = "primary",
  size = "compact",
  disabled = false,
}: ButtonProps) {
  const { colors } = useTheme();
  const { focusVisible, focusProps } = useFocusRing();

  const cor = disabled
    ? { fundo: colors.surface2, texto: colors.ink3 }
    : variant === "primary"
      ? { fundo: colors.primaryBg, texto: colors.primaryFg }
      : { fundo: colors.surface, texto: colors.ink };

  return (
    <Pressable
      role="button"
      disabled={disabled}
      onPress={onPress}
      {...focusProps}
      style={[size === "large" ? styles.toqueGrande : styles.toque, noOutline]}
    >
      {({ pressed }) => (
        <View
          testID="botao-visual"
          style={[
            size === "large" ? styles.grande : styles.discreto,
            { backgroundColor: cor.fundo },
            pressed && { opacity: interacao.opacidadePressionado },
            focusVisible && focusRingStyle(colors.focus),
          ]}
        >
          <Text
            numberOfLines={1}
            style={[
              size === "large" ? styles.textoGrande : styles.texto,
              { color: cor.texto },
            ]}
          >
            {label}
          </Text>
        </View>
      )}
    </Pressable>
  );
}

const styles = StyleSheet.create({
  toque: { minHeight: tamanhos.alvoDeToque, justifyContent: "center" },
  toqueGrande: { alignSelf: "stretch" },
  discreto: {
    height: tamanhos.botaoDiscreto.altura,
    borderRadius: raios.botoes,
    paddingHorizontal: 12,
    alignItems: "center",
    justifyContent: "center",
  },
  grande: {
    height: tamanhos.botaoGrande,
    borderRadius: raios.botoes,
    paddingHorizontal: 16,
    alignItems: "center",
    justifyContent: "center",
  },
  texto: {
    fontFamily: fontFamily({ familia: "Instrument Sans", peso: 600 }),
    fontSize: tamanhos.botaoDiscreto.texto,
  },
  // A identidade não dá o tamanho deste texto: 15 é o da escala que mais se aproxima do login.
  textoGrande: {
    fontFamily: fontFamily({ familia: "Instrument Sans", peso: 700 }),
    fontSize: 15,
  },
});
import type { ReactNode } from "react";
import { StyleSheet, Text, View } from "react-native";

import { textStyles } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { Button } from "./Button";
import { Icon, type IconName } from "./Icon";

const TAMANHO_DO_ICONE = 32;

interface EmptyStateProps {
  title: string;
  message?: string;
  icon?: IconName;
  // Uma saída para quem chegou aqui, quando houver.
  action?: { label: string; onPress: () => void };
}

export function EmptyState({
  title,
  message,
  icon = "inbox",
  action,
}: EmptyStateProps) {
  const { colors } = useTheme();

  return (
    <StateLayout
      icon={<Icon name={icon} color={colors.ink2} size={TAMANHO_DO_ICONE} />}
      title={title}
      message={message}
      action={action}
    />
  );
}

interface ErrorStateProps {
  title?: string;
  message?: string;
  // Sem isso, a tela só informa. Com isso, oferece tentar de novo.
  onRetry?: () => void;
}

// Todo erro em tela vira isto: mensagem amigável, nunca o erro cru. `like` só no ícone.
export function ErrorState({
  title = "Não deu certo agora.",
  message = "Tente de novo em instantes.",
  onRetry,
}: ErrorStateProps) {
  const { colors } = useTheme();

  return (
    <StateLayout
      role="alert"
      icon={<Icon name="alert" color={colors.like} size={TAMANHO_DO_ICONE} />}
      title={title}
      message={message}
      action={
        onRetry ? { label: "Tentar de novo", onPress: onRetry } : undefined
      }
    />
  );
}

function StateLayout({
  role,
  icon,
  title,
  message,
  action,
}: {
  role?: "alert";
  icon: ReactNode;
  title: string;
  message?: string;
  action?: { label: string; onPress: () => void };
}) {
  const { colors } = useTheme();

  return (
    <View style={styles.coluna}>
      {icon}
      {/* O anúncio fica só no texto: envolvendo o botão, ele o esconderia do leitor de tela. */}
      <View accessible={!!role} role={role} style={styles.textos}>
        <Text style={[styles.centro, textStyles.secao, { color: colors.ink }]}>
          {title}
        </Text>
        {message && (
          <Text
            style={[styles.centro, textStyles.corpo, { color: colors.ink2 }]}
          >
            {message}
          </Text>
        )}
      </View>
      {action && (
        <Button
          label={action.label}
          variant="secondary"
          onPress={action.onPress}
        />
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  coluna: {
    alignItems: "center",
    paddingVertical: 32,
    paddingHorizontal: 16,
    gap: 12,
  },
  textos: { alignItems: "center", gap: 4 },
  centro: { textAlign: "center" },
});
