import { createApiClient, type ApiClient } from "@maxx/api-client";
import { createContext, useContext, type ReactNode } from "react";
import { Platform } from "react-native";

// Origem única (ADR 0001): na web a API está no mesmo host, sob /api. No nativo, a URL
// pública vem de EXPO_PUBLIC_API_URL, que não é segredo e vai para o binário.
export function defaultBaseUrl(): string {
  return Platform.OS === "web" ? "" : (process.env.EXPO_PUBLIC_API_URL ?? "");
}

const ApiClientContext = createContext<ApiClient | null>(null);

export function ApiClientProvider({
  client,
  children,
}: {
  client: ApiClient;
  children: ReactNode;
}) {
  return (
    <ApiClientContext.Provider value={client}>
      {children}
    </ApiClientContext.Provider>
  );
}

export function useApiClient(): ApiClient {
  const client = useContext(ApiClientContext);
  if (!client) {
    throw new Error("useApiClient fora do ApiClientProvider.");
  }
  return client;
}

export { createApiClient };
import { useQuery } from "@tanstack/react-query";

import { useApiClient } from "./ApiClientProvider";

export type HealthResult = { httpStatus: number; status: string };

export function useHealth() {
  const client = useApiClient();

  return useQuery({
    queryKey: ["health"],
    queryFn: async (): Promise<HealthResult> => {
      const { data, response } = await client.GET("/api/health");
      if (!response.ok || !data) {
        throw new Error(`GET /api/health respondeu ${response.status}.`);
      }
      return { httpStatus: response.status, status: data.status };
    },
  });
}
import { useState } from "react";
import {
  Pressable,
  StyleSheet,
  Text,
  TextInput,
  View,
  type TextInputProps,
} from "react-native";

import { fontFamily } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { interacao, raios, tamanhos } from "../theme/tokens";
import { focusRingStyle, noOutline, useFocusRing } from "./focusRing";
import { Icon } from "./Icon";

interface TextFieldProps extends Omit<
  TextInputProps,
  "style" | "editable" | "secureTextEntry" | "placeholderTextColor"
> {
  label: string;
  // Esconde o texto e oferece o botão de mostrar.
  password?: boolean;
  disabled?: boolean;
}

const RECUO = 14;

export function TextField({
  label,
  password = false,
  disabled = false,
  onFocus,
  onBlur,
  ...input
}: TextFieldProps) {
  const { colors } = useTheme();
  const [focused, setFocused] = useState(false);
  const [revealed, setRevealed] = useState(false);
  const borda = focused ? interacao.bordaDeCampoEmFoco : interacao.bordaDeCampo;

  return (
    <View style={styles.coluna}>
      <Text style={[styles.rotulo, { color: colors.ink }]}>{label}</Text>
      <View
        testID="campo-caixa"
        style={[
          styles.caixa,
          {
            borderWidth: borda,
            borderColor: focused ? colors.focus : colors.fieldLine,
            backgroundColor: disabled ? colors.surface2 : colors.fieldBg,
            // A borda mais grossa do foco não pode empurrar o texto.
            paddingLeft: RECUO - borda,
          },
        ]}
      >
        <TextInput
          autoCapitalize={password ? "none" : undefined}
          autoCorrect={password ? false : undefined}
          {...input}
          aria-label={label}
          editable={!disabled}
          secureTextEntry={password && !revealed}
          placeholderTextColor={colors.ink3}
          onFocus={(event) => {
            setFocused(true);
            onFocus?.(event);
          }}
          onBlur={(event) => {
            setFocused(false);
            onBlur?.(event);
          }}
          style={[
            styles.entrada,
            noOutline,
            { color: disabled ? colors.ink3 : colors.ink },
          ]}
        />
        {password && (
          <RevealButton
            revealed={revealed}
            disabled={disabled}
            onPress={() => setRevealed((atual) => !atual)}
          />
        )}
      </View>
    </View>
  );
}

function RevealButton({
  revealed,
  disabled,
  onPress,
}: {
  revealed: boolean;
  disabled: boolean;
  onPress: () => void;
}) {
  const { colors } = useTheme();
  const { focusVisible, focusProps } = useFocusRing();

  return (
    <Pressable
      role="button"
      aria-label={revealed ? "Ocultar senha" : "Mostrar senha"}
      disabled={disabled}
      onPress={onPress}
      {...focusProps}
      style={({ pressed }) => [
        styles.mostrar,
        noOutline,
        pressed && { opacity: interacao.opacidadePressionado },
        focusVisible && focusRingStyle(colors.focus),
      ]}
    >
      <Icon
        name={revealed ? "eyeOff" : "eye"}
        color={disabled ? colors.ink3 : colors.ink2}
      />
    </Pressable>
  );
}

