using System.ComponentModel.DataAnnotations;
using Maxx.Api.LimiteDeTaxa;
using Maxx.Application.Autenticacao.Cadastro;
using Microsoft.AspNetCore.Http.HttpResults;

namespace Maxx.Api.Autenticacao;

// O cadastro do aluno pelo app. RA e e-mail vão no corpo, nunca na URL: são dado pessoal
// e não podem parar em log de acesso.
internal static class CadastroEndpoints
{
    public static IEndpointRouteBuilder MapCadastroEndpoints(this IEndpointRouteBuilder auth)
    {
        var cadastro = auth.MapGroup("/cadastro").WithTags("Autenticacao");

        cadastro.MapPost("/sugestao", SugerirAsync)
            .WithName("SugerirArroba")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict)
            .ComLimiteDeTaxa(Limite.ConsultaDeCadastroPorIp, contexto => LimiteDeTaxaExtensions.Ip(contexto.HttpContext));

        cadastro.MapPost("/disponibilidade", VerificarDisponibilidadeAsync)
            .WithName("VerificarDisponibilidadeDoPrefixo")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict)
            .ComLimiteDeTaxa(Limite.ConsultaDeCadastroPorIp, contexto => LimiteDeTaxaExtensions.Ip(contexto.HttpContext));

        cadastro.MapPost("", CadastrarAsync)
            .WithName("Cadastrar")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict)
            .ComLimiteDeTaxa(Limite.CadastroPorRa, contexto => LimiteDeTaxaExtensions.Do<CadastroRequest>(contexto, pedido => pedido.Ra));

        return auth;
    }

    private static async Task<Ok<SugestaoResponse>> SugerirAsync(
        IdentificacaoRequest pedido, CadastroHandler handler, CancellationToken cancellationToken)
    {
        var arroba = await handler.SugerirAsync(pedido.Ra, pedido.Email, cancellationToken);
        return TypedResults.Ok(new SugestaoResponse(arroba.Prefixo, arroba.Sufixo, arroba.ToString()));
    }

    private static async Task<Ok<DisponibilidadeResponse>> VerificarDisponibilidadeAsync(
        DisponibilidadeRequest pedido, CadastroHandler handler, CancellationToken cancellationToken) =>
        TypedResults.Ok(new DisponibilidadeResponse(
            await handler.PrefixoDisponivelAsync(pedido.Ra, pedido.Email, pedido.Prefixo, cancellationToken)));

    private static async Task<Created<SessaoResponse>> CadastrarAsync(
        CadastroRequest pedido, CadastroHandler handler, HttpContext httpContext, CancellationToken cancellationToken)
    {
        var sessao = await handler.CadastrarAsync(
            new NovoCadastro(pedido.Ra, pedido.Email, pedido.NomeDeExibicao, pedido.Prefixo, pedido.Senha), cancellationToken);
        return TypedResults.Created((string?)null, SessaoHttp.Escrever(httpContext, sessao));
    }
}

// Na borda só presença e teto de tamanho; a forma do prefixo, da senha e do nome é regra
// do domínio e volta com código próprio.
public sealed record IdentificacaoRequest(
    [property: Required, StringLength(32)] string Ra,
    [property: Required, StringLength(254)] string Email);

public sealed record DisponibilidadeRequest(
    [property: Required, StringLength(32)] string Ra,
    [property: Required, StringLength(254)] string Email,
    [property: Required(AllowEmptyStrings = true), StringLength(64)] string Prefixo);

public sealed record CadastroRequest(
    [property: Required, StringLength(32)] string Ra,
    [property: Required, StringLength(254)] string Email,
    [property: Required(AllowEmptyStrings = true), StringLength(240)] string NomeDeExibicao,
    [property: Required(AllowEmptyStrings = true), StringLength(64)] string Prefixo,
    [property: Required(AllowEmptyStrings = true), StringLength(512)] string Senha)
{
    public override string ToString() => $"CadastroRequest {{ Ra = {Ra}, Prefixo = {Prefixo} }}";
}

public sealed record SugestaoResponse(string Prefixo, string Sufixo, string Arroba);

public sealed record DisponibilidadeResponse(bool Disponivel);
using System.Security.Claims;
using Maxx.Application.Autenticacao;
using Microsoft.AspNetCore.Http.HttpResults;

namespace Maxx.Api.Autenticacao;

internal static class EuEndpoints
{
    // Quem é o dono do access token, lido do banco: o token só diz quem é, e o arroba pode
    // ter mudado depois da emissão. Cresce só por acréscimo.
    public static IEndpointRouteBuilder MapEuEndpoints(this IEndpointRouteBuilder routes)
    {
        routes.MapGet("/eu", GetEuAsync)
            .WithName("GetEu")
            .WithTags("Autenticacao")
            .RequireAuthorization()
            .ProducesProblem(StatusCodes.Status401Unauthorized);

        return routes;
    }

    private static async Task<Results<Ok<EuResponse>, UnauthorizedHttpResult>> GetEuAsync(
        ClaimsPrincipal principal, IUsuarioRepository usuarios, CancellationToken cancellationToken)
    {
        if (!Guid.TryParse(principal.FindFirstValue(MaxxClaims.Sub), out var id)
            || await usuarios.BuscarAsync(id, cancellationToken) is not { } usuario)
        {
            return TypedResults.Unauthorized();
        }

        return TypedResults.Ok(new EuResponse(
            usuario.Id, JwtAccessTokenIssuer.NomesDosPapeis(usuario.Papeis), usuario.Arroba.ToString()));
    }
}

public sealed record EuResponse(Guid Id, IReadOnlyList<string> Papeis, string Arroba);
using System.ComponentModel.DataAnnotations;
using Maxx.Api.Erros;
using Maxx.Api.LimiteDeTaxa;
using Maxx.Application.Autenticacao;
using Maxx.Application.Autenticacao.Login;
using Microsoft.AspNetCore.Http.HttpResults;

namespace Maxx.Api.Autenticacao;

// Login, renovação e logout (fluxos/01-login.md). Na web o refresh anda só em cookie; no
// nativo, só no corpo (SessaoHttp).
internal static partial class LoginEndpoints
{
    public static IEndpointRouteBuilder MapLoginEndpoints(this IEndpointRouteBuilder auth)
    {
        var grupo = auth.MapGroup("").WithTags("Autenticacao");

        grupo.MapPost("/login", EntrarAsync)
            .WithName("Entrar")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status401Unauthorized)
            .ComLimiteDeTaxa(Limite.LoginPorIp, contexto => LimiteDeTaxaExtensions.Ip(contexto.HttpContext))
            .ComLimiteDeTaxa(
                Limite.LoginPorIdentificador,
                contexto => LimiteDeTaxaExtensions.Do<LoginRequest>(contexto, pedido => pedido.Identificador));

        grupo.MapPost("/refresh", RenovarAsync)
            .WithName("RenovarSessao")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status401Unauthorized);

        grupo.MapPost("/logout", SairAsync)
            .WithName("Sair")
            .ProducesValidationProblem();

        return auth;
    }

    private static async Task<Ok<SessaoResponse>> EntrarAsync(
        LoginRequest pedido, LoginHandler handler, HttpContext httpContext, CancellationToken cancellationToken)
    {
        var sessao = await handler.EntrarAsync(new Credenciais(pedido.Identificador, pedido.Senha), cancellationToken);
        return TypedResults.Ok(SessaoHttp.Escrever(httpContext, sessao));
    }

    private static async Task<Results<Ok<SessaoResponse>, ProblemHttpResult>> RenovarAsync(
        RefreshRequest? pedido,
        RefreshHandler handler,
        HttpContext httpContext,
        ILoggerFactory loggers,
        CancellationToken cancellationToken)
    {
        var refresh = SessaoHttp.LerRefresh(httpContext.Request, pedido?.RefreshToken);
        var renovacao = refresh is null
            ? Renovacao.Recusada(RecusaDaRenovacao.Desconhecido)
            : await handler.RenovarAsync(refresh, cancellationToken);

        if (renovacao.Sessao is { } sessao)
        {
            return TypedResults.Ok(SessaoHttp.Escrever(httpContext, sessao));
        }

        var logger = loggers.CreateLogger(typeof(LoginEndpoints));
        if (renovacao.Recusa == RecusaDaRenovacao.ReusoDetectado)
        {
            LogReuso(logger, renovacao.FamiliaId);
        }
        else
        {
            LogRecusada(logger, renovacao.Recusa, renovacao.FamiliaId);
        }

        SessaoHttp.Apagar(httpContext);
        return TypedResults.Problem(
            statusCode: StatusCodes.Status401Unauthorized,
            extensions: new Dictionary<string, object?> { [Erro.CampoCodigo] = CodigosDeRecusa.SessaoInvalida });
    }

    // Sempre 204: refresh desconhecido ou família já revogada não muda a resposta.
    private static async Task<NoContent> SairAsync(
        RefreshRequest? pedido, LogoutHandler handler, HttpContext httpContext, CancellationToken cancellationToken)
    {
        if (SessaoHttp.LerRefresh(httpContext.Request, pedido?.RefreshToken) is { } refresh)
        {
            await handler.SairAsync(refresh, cancellationToken);
        }

        SessaoHttp.Apagar(httpContext);
        return TypedResults.NoContent();
    }

    [LoggerMessage(Level = LogLevel.Warning, Message = "Reuso de refresh: família {FamiliaId} revogada.")]
    private static partial void LogReuso(ILogger logger, Guid? familiaId);

    [LoggerMessage(Level = LogLevel.Information, Message = "Renovação recusada ({Recusa}), família {FamiliaId}.")]
    private static partial void LogRecusada(ILogger logger, RecusaDaRenovacao? recusa, Guid? familiaId);
}

// Identificador é o RA ou o e-mail. A senha só tem teto na borda: o Argon2id não recebe
// texto sem limite, e a política vale no cadastro, não no login.
public sealed record LoginRequest(
    [property: Required, StringLength(254)] string Identificador,
    [property: Required(AllowEmptyStrings = true), StringLength(512)] string Senha)
{
    public override string ToString() => "LoginRequest { }";
}

// No nativo, o refresh vem aqui; na web o corpo pode faltar, porque ele vem do cookie.
public sealed record RefreshRequest([property: StringLength(128)] string? RefreshToken)
{
    public override string ToString() => "RefreshRequest { }";
}
