206	    private static async Task<Results<Ok<SessaoResponse>, ProblemHttpResult>> RenovarAsync(
207	        RefreshRequest? pedido,
208	        RefreshHandler handler,
209	        HttpContext httpContext,
210	        ILoggerFactory loggers,
211	        CancellationToken cancellationToken)
212	    {
213	        var refresh = SessaoHttp.LerRefresh(httpContext.Request, pedido?.RefreshToken);
214	        var renovacao = refresh is null
215	            ? Renovacao.Recusada(RecusaDaRenovacao.Desconhecido)
216	            : await handler.RenovarAsync(refresh, cancellationToken);
217	
218	        if (renovacao.Sessao is { } sessao)
219	        {
220	            return TypedResults.Ok(SessaoHttp.Escrever(httpContext, sessao));
221	        }
222	
223	        var logger = loggers.CreateLogger(typeof(LoginEndpoints));
224	        if (renovacao.Recusa == RecusaDaRenovacao.ReusoDetectado)
225	        {
226	            LogReuso(logger, renovacao.FamiliaId);
227	        }
228	        else
229	        {
230	            LogRecusada(logger, renovacao.Recusa, renovacao.FamiliaId);
231	        }
232	
233	        SessaoHttp.Apagar(httpContext);
234	        return TypedResults.Problem(
235	            statusCode: StatusCodes.Status401Unauthorized,
236	            extensions: new Dictionary<string, object?> { [Erro.CampoCodigo] = CodigosDeRecusa.SessaoInvalida });
237	    }
