469	    // concluído: em todos os casos o cliente oferece pedir um link novo.
470	    public const string RecuperacaoInvalida = "recuperacao-invalida";
471	
472	    // Demonstração: curso que não existe ou sem turma no semestre vigente.
473	    public const string CursoDeDemonstracaoIndisponivel = "curso-indisponivel";
474	
475	    // Demonstração: muita gente com o mesmo nome entrando junto, e as tentativas acabaram.
476	    // O cliente oferece tentar de novo.
477	    public const string RegistroSimultaneo = "registro-simultaneo";
478	
479	    // Demonstração: a chave guardada no dispositivo não abre conta nenhuma.
480	    public const string ChaveDoDispositivoInvalida = "chave-invalida";
481	}
