239	    // Sempre 204: refresh desconhecido ou família já revogada não muda a resposta.
240	    private static async Task<NoContent> SairAsync(
241	        RefreshRequest? pedido, LogoutHandler handler, HttpContext httpContext, CancellationToken cancellationToken)
242	    {
243	        if (SessaoHttp.LerRefresh(httpContext.Request, pedido?.RefreshToken) is { } refresh)
244	        {
245	            await handler.SairAsync(refresh, cancellationToken);
246	        }
247	
248	        SessaoHttp.Apagar(httpContext);
249	        return TypedResults.NoContent();
250	    }
