        {
            var chaves = Chaves(JsonNode.Parse(File.ReadAllText(arquivo))!).ToList();
            Assert.DoesNotContain(chaves, chave => chave.StartsWith(DemoOptions.Section, StringComparison.OrdinalIgnoreCase));
