72	// Conta, sessão e recuperação. Os invariantes do domínio repetidos no banco, como no
73	// modelo acadêmico. Dentro do agregado apaga em cascata (usuário e seus prefixos, família
74	// e seus refresh); entre agregados, nunca.
75	internal sealed class UsuarioConfiguration : IEntityTypeConfiguration<Usuario>
76	{
77	    // A forma do PrefixoDeArroba.Validar.
78	    internal const string FormaDoPrefixo = "'^[A-Za-z][A-Za-z0-9]{2,29}$'";
79	
80	    public void Configure(EntityTypeBuilder<Usuario> builder)
81	    {
82	        builder.ToTable("usuario", table =>
83	        {
84	            table.HasCheckConstraint("ck_usuario_papeis", "papeis IN (1, 2, 4, 6)");
85	            table.HasCheckConstraint("ck_usuario_prefixo", $"prefixo ~ {FormaDoPrefixo}");
86	
87	            // Só aluno vira ex-aluno, e o ex-aluno usa o sufixo EX.
88	            table.HasCheckConstraint(
89	                "ck_usuario_ex_aluno",
90	                "(ex_aluno_desde IS NULL AND sufixo <> 'EX') OR (ex_aluno_desde IS NOT NULL AND papeis = 1 AND sufixo = 'EX')");
91	
92	            // Aluno de demonstração: lote e chave juntos, sem senha (produto.md 11).
93	            table.HasCheckConstraint(
94	                "ck_usuario_demonstracao",
95	                "(lote_da_demonstracao IS NULL AND hash_da_chave_do_dispositivo IS NULL) " +
96	                "OR (lote_da_demonstracao IS NOT NULL AND hash_da_chave_do_dispositivo IS NOT NULL AND papeis = 1 AND hash_da_senha IS NULL)");
97	        });
98	        builder.HasKey(usuario => usuario.Id);
99	        builder.Property(usuario => usuario.Id).ValueGeneratedNever();
100	
101	        // Um RA, uma conta: a linha do cadastro elegível aceita um usuário só.
102	        builder.HasIndex(usuario => usuario.CadastroElegivelId).IsUnique();
103	        builder.HasOne<CadastroElegivel>()
104	            .WithMany()
105	            .HasForeignKey(usuario => usuario.CadastroElegivelId)
106	            .OnDelete(DeleteBehavior.Restrict);
107	
108	        builder.Property(usuario => usuario.Papeis).HasConversion<int>();
109	        // varchar(n) no Postgres conta caractere, como o domínio: um emoji é um.
110	        builder.Property(usuario => usuario.NomeDeExibicao).HasMaxLength(Usuario.TamanhoMaximoDoNomeDeExibicao).IsRequired();
111	
112	        // A unicidade do prefixo mora em prefixo_reservado; aqui é só o atual, como escrito.
113	        builder.Property(usuario => usuario.Prefixo).HasColumnType("citext").IsRequired();
114	        builder.Property(usuario => usuario.Sufixo).IsRequired();
115	        builder.Property(usuario => usuario.HashDaSenha);
116	
117	        // A purga apaga por lote; a volta pelo dispositivo busca pelo hash da chave.
118	        builder.Property(usuario => usuario.LoteDaDemonstracao).HasMaxLength(64);
119	        builder.HasIndex(usuario => usuario.LoteDaDemonstracao).HasFilter("lote_da_demonstracao IS NOT NULL");
120	        builder.HasIndex(usuario => usuario.HashDaChaveDoDispositivo).IsUnique().HasFilter("hash_da_chave_do_dispositivo IS NOT NULL");
121	
122	        builder.HasMany(usuario => usuario.PrefixosReservados)
123	            .WithOne()
124	            .HasForeignKey(reservado => reservado.UsuarioId)
125	            .OnDelete(DeleteBehavior.Cascade);
126	        builder.Navigation(usuario => usuario.PrefixosReservados).HasField("_prefixosReservados");
127	
128	        builder.Ignore(usuario => usuario.Arroba);
129	        builder.Ignore(usuario => usuario.TemSenha);
130	        builder.Ignore(usuario => usuario.EhExAluno);
131	        builder.Ignore(usuario => usuario.EhDemonstracao);
132	    }
133	}
