135	internal sealed class PrefixoReservadoConfiguration : IEntityTypeConfiguration<PrefixoReservado>
136	{
137	    public void Configure(EntityTypeBuilder<PrefixoReservado> builder)
138	    {
139	        builder.ToTable("prefixo_reservado", table =>
140	            table.HasCheckConstraint("ck_prefixo_reservado_prefixo", $"prefixo ~ {UsuarioConfiguration.FormaDoPrefixo}"));
141	
142	        // A chave é o próprio prefixo, em citext: um dono só, para sempre, sem diferenciar
143	        // maiúsculas (produto.md 2.3.1). É o que decide a corrida entre dois cadastros.
144	        builder.HasKey(reservado => reservado.Prefixo);
145	        builder.Property(reservado => reservado.Prefixo).HasColumnType("citext");
146	        builder.HasIndex(reservado => reservado.UsuarioId);
147	    }
