150	internal sealed class FamiliaDeSessaoConfiguration : IEntityTypeConfiguration<FamiliaDeSessao>
151	{
152	    public void Configure(EntityTypeBuilder<FamiliaDeSessao> builder)
153	    {
154	        builder.ToTable("familia_sessao", table =>
155	            table.HasCheckConstraint(
156	                "ck_familia_sessao_revogacao",
157	                "(revogada_em IS NULL AND motivo_da_revogacao IS NULL) " +
158	                "OR (revogada_em IS NOT NULL AND motivo_da_revogacao IN (1, 2, 3))"));
159	        builder.HasKey(familia => familia.Id);
160	        builder.Property(familia => familia.Id).ValueGeneratedNever();
161	        builder.Property(familia => familia.MotivoDaRevogacao).HasConversion<int?>();
162	
163	        // "As famílias ativas do usuário", que a senha redefinida revoga.
164	        builder.HasIndex(familia => familia.UsuarioId).HasFilter("revogada_em IS NULL");
165	        builder.HasOne<Usuario>()
166	            .WithMany()
167	            .HasForeignKey(familia => familia.UsuarioId)
168	            .OnDelete(DeleteBehavior.Restrict);
169	
170	        builder.HasMany(familia => familia.Tokens)
171	            .WithOne()
172	            .HasForeignKey(token => token.FamiliaId)
173	            .OnDelete(DeleteBehavior.Cascade);
174	        builder.Navigation(familia => familia.Tokens).HasField("_tokens");
175	
176	        builder.Ignore(familia => familia.EstaAtiva);
177	    }
178	}
