180	internal sealed class RefreshTokenConfiguration : IEntityTypeConfiguration<RefreshToken>
181	{
182	    public void Configure(EntityTypeBuilder<RefreshToken> builder)
183	    {
184	        builder.ToTable("refresh_token", table =>
185	            table.HasCheckConstraint("ck_refresh_token_validade", "expira_em > emitido_em"));
186	        builder.HasKey(token => token.Id);
187	        builder.Property(token => token.Id).ValueGeneratedNever();
188	
189	        // O refresh chega pelo hash: é a busca de toda renovação.
190	        builder.Property(token => token.Hash).IsRequired();
191	        builder.HasIndex(token => token.Hash).IsUnique();
192	
193	        // Duas renovações simultâneas com o mesmo refresh: as duas marcam a mesma linha
194	        // como rotacionada, e o xmin deixa só a primeira gravar.
195	        builder.Property<uint>("Versao").IsRowVersion();
196	    }
197	}
