199	internal sealed class RecuperacaoDeSenhaConfiguration : IEntityTypeConfiguration<RecuperacaoDeSenha>
200	{
201	    public void Configure(EntityTypeBuilder<RecuperacaoDeSenha> builder)
202	    {
203	        builder.ToTable("recuperacao_senha", table =>
204	        {
205	            table.HasCheckConstraint("ck_recuperacao_senha_validade", "expira_em > solicitada_em");
206	            table.HasCheckConstraint(
207	                "ck_recuperacao_senha_encerramento", "usada_em IS NULL OR invalidada_em IS NULL");
208	        });
209	        builder.HasKey(recuperacao => recuperacao.Id);
210	        builder.Property(recuperacao => recuperacao.Id).ValueGeneratedNever();
211	
212	        builder.Property(recuperacao => recuperacao.Hash).IsRequired();
213	        builder.HasIndex(recuperacao => recuperacao.Hash).IsUnique();
214	
215	        // "Os outros pedidos pendentes do usuário", que a conclusão invalida.
216	        builder.HasIndex(recuperacao => recuperacao.UsuarioId).HasFilter("usada_em IS NULL AND invalidada_em IS NULL");
217	        builder.HasOne<Usuario>()
218	            .WithMany()
219	            .HasForeignKey(recuperacao => recuperacao.UsuarioId)
220	            .OnDelete(DeleteBehavior.Restrict);
221	
222	        // O mesmo link usado duas vezes ao mesmo tempo: só um grava.
223	        builder.Property<uint>("Versao").IsRowVersion();
224	    }
225	}
