494	    public static async Task SalvarAsync(MaxxApiFactory factory, params object[] entidades)
495	    {
496	        await using var scope = factory.Services.CreateAsyncScope();
497	        var db = scope.ServiceProvider.GetRequiredService<MaxxDbContext>();
498	        db.AddRange(entidades);
499	        await db.SaveChangesAsync(Ct);
