    public void RemoverItem(string arquivo, string codigo) =>
        Alterar($"catalogo/{arquivo}", raiz =>
        {
            var itens = raiz["itens"]!.AsArray();
            itens.Remove(itens.Single(item => (string?)item!["codigo"] == codigo));
