namespace Maxx.Domain.Identidade;

// O termo que o aluno aceita ao criar a conta (produto.md 2.6). Uma versão publicada nunca
// muda: quem a aceitou, aceitou aquele texto. A vigente é a de número mais alto.
public sealed class TermoDeUso
{
    // Para o EF Core materializar do banco.
    private TermoDeUso()
    {
        Conteudo = null!;
    }

    public TermoDeUso(int versao, string conteudo, DateTimeOffset publicadoEm)
    {
        if (versao < 1)
        {
            throw new DomainException($"A versão do termo de uso começa em 1, não em {versao}.");
        }

        Versao = versao;
        Conteudo = Texto.Obrigatorio(conteudo, "O texto do termo de uso");
        PublicadoEm = publicadoEm;
    }

    public int Versao { get; private set; }

    public string Conteudo { get; private set; }

    public DateTimeOffset PublicadoEm { get; private set; }
}

// Quem aceitou qual versão, e quando.
public sealed class AceiteDeTermo
{
    internal AceiteDeTermo(Guid usuarioId, int versao, DateTimeOffset aceitoEm)
    {
        UsuarioId = usuarioId;
        Versao = versao;
        AceitoEm = aceitoEm;
    }

    public Guid UsuarioId { get; private set; }

    public int Versao { get; private set; }

    public DateTimeOffset AceitoEm { get; private set; }
}

using Maxx.Domain.Identidade;

namespace Maxx.Application.Autenticacao.Termos;

// O termo de uso vigente, e a conferência do que o aluno disse ter aceitado.
public sealed class TermoDeUsoHandler(ITermoDeUsoRepository termos)
{
    public async Task<TermoDeUso> VigenteAsync(CancellationToken cancellationToken) =>
        await termos.VigenteAsync(cancellationToken)
            ?? throw new RecusaException(TipoDeRecusa.NaoEncontrado, CodigosDeRecusa.TermoIndisponivel, "Nenhum termo de uso publicado.");

    // O aluno aceita o texto que leu. Se a versão mudou enquanto ele lia, a conta não nasce
    // com o aceite de um texto que já não vale.
    public async Task<TermoDeUso> ConferirAceiteAsync(int versaoAceita, CancellationToken cancellationToken)
    {
        var vigente = await termos.VigenteAsync(cancellationToken);
        return vigente?.Versao == versaoAceita
            ? vigente
            : throw new RecusaException(
                TipoDeRecusa.Conflito, CodigosDeRecusa.TermoDesatualizado, $"Aceite da versão {versaoAceita}, vigente {vigente?.Versao}.");
    }
}

using Maxx.Application.Autenticacao.Termos;
using Microsoft.AspNetCore.Http.HttpResults;

namespace Maxx.Api.Autenticacao;

// O texto vem da API, e não do bundle: o app instalado atrasa, e o aceite tem de ser do
// texto vigente. Público, porque quem o lê ainda não tem conta.
internal static class TermoDeUsoEndpoints
{
    public static IEndpointRouteBuilder MapTermoDeUsoEndpoints(this IEndpointRouteBuilder v1)
    {
        v1.MapGet("/termo-de-uso", VigenteAsync)
            .WithName("GetTermoDeUso")
            .WithTags("Autenticacao")
            .AllowAnonymous()
            .ProducesProblem(StatusCodes.Status404NotFound);

        return v1;
    }

    private static async Task<Ok<TermoDeUsoResponse>> VigenteAsync(TermoDeUsoHandler handler, CancellationToken cancellationToken)
    {
        var termo = await handler.VigenteAsync(cancellationToken);
        return TypedResults.Ok(new TermoDeUsoResponse(termo.Versao, termo.Conteudo));
    }
}

public sealed record TermoDeUsoResponse(int Versao, string Texto);

using System.Globalization;
using System.Text.RegularExpressions;

namespace Maxx.Infrastructure.Seed;

// Lê data/termos/termo-de-uso.v<versão>.md, um arquivo por versão.
public static partial class TermoDeUsoReader
{
    public static IReadOnlyDictionary<int, string> Ler(string diretorio)
    {
        if (!Directory.Exists(diretorio))
        {
            throw new SeedException($"Diretório dos termos não encontrado: {diretorio}.");
        }

        var versoes = new SortedDictionary<int, string>();
        foreach (var arquivo in Directory.GetFiles(diretorio))
        {
            var nome = Path.GetFileName(arquivo);
            var encontrado = NomeDoArquivo().Match(nome);
            if (!encontrado.Success)
            {
                throw new SeedException($"Arquivo fora do padrão termo-de-uso.v<versão>.md: {nome}.");
            }

            // Fim de linha do checkout (CRLF no Windows) não é mudança de texto.
            versoes[int.Parse(encontrado.Groups[1].ValueSpan, CultureInfo.InvariantCulture)] =
                File.ReadAllText(arquivo).ReplaceLineEndings("\n").Trim();
        }

        return versoes.Count > 0 ? versoes : throw new SeedException($"Nenhum termo de uso em {diretorio}.");
    }

    [GeneratedRegex(@"^termo-de-uso\.v([1-9][0-9]{0,8})\.md$", RegexOptions.CultureInvariant)]
    private static partial Regex NomeDoArquivo();
}

