const raiz = "C:/Users/Guilherme Gimenes/Documents/Repos/tcc/maxx-engenheiro/apps/api/tests/Maxx.Api.IntegrationTests/";
function ed(f, fn) {
  const p = raiz + f;
  const bruto = fs.readFileSync(p, "utf8");
  const crlf = bruto.includes("\r\n");
  const s = crlf ? bruto.replace(/\r\n/g, "\n") : bruto;
  const n = fn(s);
  if (n === s) throw new Error("sem mudanca " + f);
  fs.writeFileSync(p, crlf ? n.replace(/\n/g, "\r\n") : n);
}
function rep(s, a, b) {
  if (!s.includes(a)) throw new Error("nao achei: " + a);
  return s.replace(a, () => b);
}
