const MENSAGENS = {
  // Autenticação (CodigosDeRecusa.cs)
  "cadastro-nao-encontrado": "Não achamos esse RA com esse e-mail. Confira os dois.",
  "conta-existente": "Esse RA já tem conta. Use Esqueci minha senha para entrar.",
