import { readFileSync } from "fs";
import { join } from "path";

import {
  codigoDoErro,
  codigosConhecidos,
  mensagemDaFalha,
  mensagemDeErro,
} from "./erros";

const API = join(__dirname, "../../../api/src");

// Os códigos que a API pode mandar, lidos do próprio código dela.
function codigosDaApi(): string[] {
  const recusas = readFileSync(
    join(API, "Maxx.Application/Autenticacao/CodigosDeRecusa.cs"),
    "utf8",
  );
  const erros = readFileSync(join(API, "Maxx.Api/Erros/Erro.cs"), "utf8");
  const literais = (texto: string, padrao: RegExp) =>
    [...texto.matchAll(padrao)].map((m) => m[1]!);

  return [
    ...literais(recusas, /const string \w+ = "([a-z-]+)";/g),
    ...literais(erros, /=> "([a-z-]+)"/g),
  ];
}

describe("mensagens de erro", () => {
  it("todo código que a API manda tem mensagem própria", () => {
    const daApi = codigosDaApi();

    expect(daApi).toEqual(
      expect.arrayContaining(["registro-simultaneo", "dados-invalidos"]),
    );
    for (const codigo of daApi) {
      expect(codigosConhecidos).toContain(codigo);
    }
  });

  it("registro-simultaneo diz o que houve e convida a tentar de novo", () => {
    expect(mensagemDeErro("registro-simultaneo")).toBe(
      "Muita gente entrou com esse nome agora. Tente de novo em instantes.",
    );
  });

  it("código desconhecido, ou nenhum, cai na mensagem padrão", () => {
    const padrao = "Não deu certo agora. Tente de novo em instantes.";

    expect(mensagemDeErro("codigo-de-uma-api-mais-nova")).toBe(padrao);
    expect(mensagemDeErro(undefined)).toBe(padrao);
    expect(mensagemDeErro("toString")).toBe(padrao);
  });

  it("lê o código do ProblemDetails e ignora o que não é", () => {
    expect(codigoDoErro({ status: 409, codigo: "conta-existente" })).toBe(
      "conta-existente",
    );
    expect(codigoDoErro({ codigo: 42 })).toBeUndefined();
    expect(codigoDoErro("texto")).toBeUndefined();
    expect(codigoDoErro(null)).toBeUndefined();
  });

  it("falha de rede vira sem conexão, e o resto, a padrão, nunca o erro cru", () => {
    expect(mensagemDaFalha(new TypeError("Network request failed"))).toBe(
      "Sem conexão. Confira a internet e tente de novo.",
    );
    expect(mensagemDaFalha(new Error("stack trace interno"))).toBe(
      "Não deu certo agora. Tente de novo em instantes.",
    );
  });

  it("nenhuma mensagem tem emoji nem travessão", () => {
    for (const codigo of codigosConhecidos) {
      const texto = mensagemDeErro(codigo);
      expect(texto).not.toMatch(/\p{Extended_Pictographic}/u);
      expect(texto).not.toMatch(/[—–]/);
    }
  });
});

import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { act, render, screen } from "@testing-library/react-native";
import { Text } from "react-native";

import {
  GerenciadorDeSessao,
  type SessaoResponse,
} from "./GerenciadorDeSessao";
import { SessaoProvider, useSessao } from "./SessaoProvider";

const sessao: SessaoResponse = {
  accessToken: "a1",
  accessTokenExpiraEm: "2999-01-01T00:00:00Z",
  refreshToken: "r1",
  refreshTokenExpiraEm: "2999-01-01T00:00:00Z",
};

function Estado() {
  const { estado } = useSessao();
  return <Text testID="estado">{estado}</Text>;
}

function montar(refreshGuardado: string | null, fetch: jest.Mock) {
  let valor = refreshGuardado;
  const gerenciador = new GerenciadorDeSessao({
    baseUrl: "http://maxx.test",
    web: false,
    armazenamento: {
      ler: async () => valor,
      gravar: async (novo) => {
        valor = novo;
      },
      apagar: async () => {
        valor = null;
      },
    },
    trava: (renovacao) => renovacao(),
    fetch,
  });
  const queryClient = new QueryClient();
  return { gerenciador, queryClient };
}

async function renderizar(
  gerenciador: GerenciadorDeSessao,
  queryClient: QueryClient,
) {
  await render(
    <QueryClientProvider client={queryClient}>
      <SessaoProvider gerenciador={gerenciador}>
        <Estado />
      </SessaoProvider>
    </QueryClientProvider>,
  );
  await act(async () => {});
}

describe("SessaoProvider", () => {
  it("restaura a sessão guardada ao abrir", async () => {
    const fetch = jest.fn(
      async () => new Response(JSON.stringify(sessao), { status: 200 }),
    );
    const { gerenciador, queryClient } = montar("r0", fetch);

    await renderizar(gerenciador, queryClient);

    expect(screen.getByTestId("estado")).toHaveTextContent("autenticado");
  });

  it("sem rede ao abrir fica sem conexão, e tentar de novo entra", async () => {
    const fetch = jest.fn(async (): Promise<Response> => {
      throw new TypeError("Network request failed");
    });
    const { gerenciador, queryClient } = montar("r0", fetch);

    await renderizar(gerenciador, queryClient);
    expect(screen.getByTestId("estado")).toHaveTextContent("sem-conexao");

    fetch.mockImplementation(
      async () => new Response(JSON.stringify(sessao), { status: 200 }),
    );
    await act(() => gerenciador.restaurar());
    expect(screen.getByTestId("estado")).toHaveTextContent("autenticado");
  });

  it("ao sair, o cache de consultas da conta é esvaziado", async () => {
    const fetch = jest.fn(
      async () => new Response(JSON.stringify(sessao), { status: 200 }),
    );
    const { gerenciador, queryClient } = montar("r0", fetch);
    await renderizar(gerenciador, queryClient);
    queryClient.setQueryData(["eu"], { arroba: "@anaSouza-CC" });

    fetch.mockImplementation(async () => new Response(null, { status: 204 }));
    await act(() => gerenciador.sair());

    expect(screen.getByTestId("estado")).toHaveTextContent("anonimo");
    expect(queryClient.getQueryData(["eu"])).toBeUndefined();
  });
});

