// Gera apps/mobile/src/marca/logoVetor.ts a partir de design/assets/maxx-ouro.svg: o
// traçado do logo para o componente Logo desenhar com react-native-svg, na cor do tema.
// Roda junto com gerar.js, ou sozinho: node design/icones/logoVetor.js
const fs = require("node:fs");
const path = require("node:path");

const raiz = path.resolve(__dirname, "../..");
const ARQUIVO = path.join(raiz, "apps/mobile/src/marca/logoVetor.ts");

function gerarLogoVetor() {
  const svg = fs.readFileSync(
    path.join(raiz, "design/assets/maxx-ouro.svg"),
    "utf8",
  );
  const [, largura, altura] = svg
    .match(/viewBox="0 0 (\d+) (\d+)"/)
    .map(Number);
  const caminhos = [...svg.matchAll(/<path\b[^>]*\sd="([^"]+)"/g)].map(
    (m) => m[1],
  );
  if (caminhos.length !== 1) {
    throw new Error(`Esperado um <path> no logo, há ${caminhos.length}.`);
  }

  fs.writeFileSync(
    ARQUIVO,
    `// Gerado por design/icones/logoVetor.js a partir de design/assets/maxx-ouro.svg.
// Não editar: troque o SVG e rode node design/icones/gerar.js.
export const logoVetor = {
  largura: ${largura},
  altura: ${altura},
  caminho:
    ${JSON.stringify(caminhos[0])},
} as const;
`,
  );
  console.log(path.relative(raiz, ARQUIVO), "gerado");
}

module.exports = { gerarLogoVetor };

if (require.main === module) {
  gerarLogoVetor();
}

import Svg, { Path } from "react-native-svg";

import { useTheme } from "../theme/ThemeProvider";
import { logoVetor } from "./logoVetor";

// Altura mínima do logo (identidade-visual.md, Logo e imagens).
export const ALTURA_MINIMA_DO_LOGO = 22;

// O logo em vetor, nítido em qualquer densidade de tela. Em ouro sobre o fundo dos dois
// temas, como a identidade manda para maxx-ouro.
export function Logo({ largura }: { largura: number }) {
  const { colors } = useTheme();
  const altura = Math.max(
    ALTURA_MINIMA_DO_LOGO,
    Math.round((largura * logoVetor.altura) / logoVetor.largura),
  );

  return (
    <Svg
      role="img"
      aria-label="Maxx"
      testID="logo"
      width={(altura * logoVetor.largura) / logoVetor.altura}
      height={altura}
      viewBox={`0 0 ${logoVetor.largura} ${logoVetor.altura}`}
    >
      <Path d={logoVetor.caminho} fill={colors.gold} fillRule="evenodd" />
    </Svg>
  );
}

import { Pressable, StyleSheet, Text } from "react-native";

import { textStyles } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { interacao, raios, tamanhos } from "../theme/tokens";
import { focusRingStyle, noOutline, useFocusRing } from "./focusRing";

interface TextLinkProps {
  label: string;
  onPress: () => void;
  disabled?: boolean;
}

// Ação em texto, como o "Esqueci minha senha" da prancheta do login: discreta, em ink2,
// com os 44 de toque de todo controle.
export function TextLink({ label, onPress, disabled = false }: TextLinkProps) {
  const { colors } = useTheme();
  const { focusVisible, focusProps } = useFocusRing();

  return (
    <Pressable
      role="link"
      aria-label={label}
      disabled={disabled}
      onPress={onPress}
      {...focusProps}
      style={({ pressed }) => [
        styles.toque,
        noOutline,
        pressed && { opacity: interacao.opacidadePressionado },
        focusVisible && focusRingStyle(colors.focus),
      ]}
    >
      <Text
        style={[textStyles.corpo, { color: disabled ? colors.ink3 : colors.ink2 }]}
      >
        {label}
      </Text>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  toque: {
    minHeight: tamanhos.alvoDeToque,
    justifyContent: "center",
    borderRadius: raios.botoes,
  },
});

import type { ReactNode } from "react";
import { Image, StyleSheet, Text, View } from "react-native";

import { Screen } from "../components/Screen";
import { Logo } from "../marca/Logo";
import { textStyles } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";

// Largura do logo nas pranchetas de login e cadastro.
const LARGURA_DO_LOGO = 245;
const SELO = 28;

interface TelaDeAutenticacaoProps {
  // O controle Entrar / Cadastrar, nas telas que o têm.
  segmentado?: ReactNode;
  children: ReactNode;
}

// A moldura comum de login, cadastro, termo, recuperação e demonstração, como nas
// pranchetas: logo e frase no alto, o conteúdo, e o selo da rede no pé. Rola quando o
// conteúdo não cabe, e o pé fica no fim da tela quando cabe.
export function TelaDeAutenticacao({
  segmentado,
  children,
}: TelaDeAutenticacaoProps) {
  const { colors } = useTheme();

  return (
    <Screen scroll>
      <View style={styles.tela}>
        <View style={styles.conteudo}>
          <View style={styles.marca}>
            <Logo largura={LARGURA_DO_LOGO} />
            <Text style={[textStyles.corpo, styles.frase, { color: colors.ink2 }]}>
              A rede de conquistas da UniMax
            </Text>
          </View>
          {segmentado}
          {children}
        </View>

        <View style={styles.rodape}>
          <Image
            source={require("../../../../design/assets/unimax.png")}
            style={styles.selo}
            accessibilityIgnoresInvertColors
            alt=""
          />
          <Text style={[textStyles.corpo, { color: colors.ink2 }]}>
            Rede UniEduk · UniMax e UniFaj
          </Text>
        </View>
      </View>
    </Screen>
  );
}

const styles = StyleSheet.create({
  tela: { flexGrow: 1, justifyContent: "space-between", gap: 32 },
  conteudo: { gap: 24, paddingTop: 72 },
  marca: { alignItems: "center", gap: 8 },
  frase: { fontSize: 16, lineHeight: 22 },
  rodape: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "center",
    gap: 12,
    paddingTop: 16,
  },
  selo: { width: SELO, height: SELO, borderRadius: 6 },
});

