  expect(caixa().height).toBe(sem);
});

test("no escuro, a borda do erro é o like do escuro", async () => {
  await renderWithTheme(<TextField label="RA" error="Confira o RA." />, "escuro");

  expect(caixa().borderColor).toBe(cores.escuro.like);
});
