// Captura as seções novas da vitrine em claro e escuro, na largura das pranchetas.
const path = require("node:path");
const raiz = "C:/Users/Guilherme Gimenes/Documents/Repos/tcc/maxx-engenheiro";
const { chromium } = require(
  require.resolve("@playwright/test", { paths: [path.join(raiz, "e2e")] }),
);
const saida = process.argv[2];

(async () => {
  const navegador = await chromium.launch();
  for (const tema of ["light", "dark"]) {
    const pagina = await navegador.newPage({
      viewport: { width: 390, height: 844 },
      deviceScaleFactor: 2,
      colorScheme: tema,
    });
    for (let tentativa = 0; tentativa < 60; tentativa++) {
      try {
        await pagina.goto("http://localhost:8099/vitrine", { timeout: 120000 });
        break;
      } catch {
        await new Promise((r) => setTimeout(r, 2000));
      }
    }
    await pagina.getByText("Marca e links").waitFor({ timeout: 180000 });
    await pagina.waitForTimeout(800);
    const nome = tema === "light" ? "claro" : "escuro";
    const campos = pagina.getByText("Campos", { exact: true });
    await campos.scrollIntoViewIfNeeded();
    const topo = await campos.boundingBox();
    const fim = await pagina
      .getByRole("link", { name: "Esqueci minha senha" })
      .last()
      .boundingBox();
    await pagina.screenshot({
      path: path.join(saida, `vitrine-etapa3-${nome}.png`),
      fullPage: true,
      clip: {
        x: 0,
        y: topo.y + (await pagina.evaluate(() => window.scrollY)) - 16,
        width: 390,
        height: fim.y - topo.y + fim.height + 32,
      },
    });
    await pagina.close();
  }
  await navegador.close();
})();

