import { StyleSheet, Text, View } from "react-native";

import { Icon } from "../components/Icon";
import { textStyles } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";

// O erro de um formulário que não é de um campo só (sem conexão, muitas tentativas). O
// mesmo desenho do erro de campo: ícone em `like`, texto em `ink`, anunciado ao aparecer.
export function AvisoDeErro({ mensagem }: { mensagem: string }) {
  const { colors } = useTheme();

  return (
    <View role="alert" aria-live="polite" accessible style={styles.linha}>
      <Icon name="alert" color={colors.like} size={16} />
      <Text style={[textStyles.legenda, styles.texto, { color: colors.ink }]}>
        {mensagem}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  linha: { flexDirection: "row", alignItems: "flex-start", gap: 8 },
  texto: { flex: 1 },
});

import { useRouter } from "expo-router";

import { SegmentedControl } from "../components/SegmentedControl";

type Acesso = "entrar" | "cadastrar";

const OPCOES = [
  { value: "entrar", label: "Entrar" },
  { value: "cadastrar", label: "Cadastrar" },
] as const;

const ROTAS = { entrar: "/login", cadastrar: "/cadastro" } as const;

// O Entrar / Cadastrar das pranchetas. Cada lado é uma rota, para o link e o voltar do
// navegador funcionarem.
export function SegmentadoDeAcesso({ atual }: { atual: Acesso }) {
  const router = useRouter();

  return (
    <SegmentedControl
      label="Acesso"
      options={OPCOES}
      value={atual}
      onChange={(acesso) => {
        if (acesso !== atual) {
          router.replace(ROTAS[acesso]);
        }
      }}
    />
  );
}

import { useMutation } from "@tanstack/react-query";
import { useRouter } from "expo-router";
import { useState } from "react";
import { StyleSheet, Text, View } from "react-native";

import { useApiClient } from "../api/ApiClientProvider";
import { codigoDoErro, mensagemDaFalha, mensagemDeErro } from "../api/erros";
import { Button } from "../components/Button";
import { TextField } from "../components/TextField";
import { TextLink } from "../components/TextLink";
import { useSessao } from "../sessao/SessaoProvider";
import { textStyles } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { AvisoDeErro } from "./AvisoDeErro";
import { SegmentadoDeAcesso } from "./SegmentadoDeAcesso";
import { TelaDeAutenticacao } from "./TelaDeAutenticacao";

// Onde cada recusa aparece: a credencial errada fica no campo da senha, como no Instagram;
// o resto, abaixo do botão.
type Falha = { campo: "senha" | "formulario"; mensagem: string };

export function LoginScreen() {
  const { colors } = useTheme();
  const client = useApiClient();
  const { iniciar } = useSessao();
  const router = useRouter();
  const [identificador, setIdentificador] = useState("");
  const [senha, setSenha] = useState("");
  const [vazios, setVazios] = useState({ identificador: false, senha: false });
  const [falha, setFalha] = useState<Falha | null>(null);

  const entrar = useMutation({
    mutationFn: async () => {
      const { data, error } = await client.POST("/api/v1/auth/login", {
        body: { identificador: identificador.trim(), senha },
      });
      if (!data) {
        const codigo = codigoDoErro(error);
        throw {
          campo: codigo === "credenciais-invalidas" ? "senha" : "formulario",
          mensagem: mensagemDeErro(codigo),
        } satisfies Falha;
      }
      // A sessão nova leva o grupo público a mandar para o início.
      await iniciar(data);
    },
    onError: (erro) =>
      setFalha(
        typeof erro === "object" && erro !== null && "campo" in erro
          ? (erro as Falha)
          : { campo: "formulario", mensagem: mensagemDaFalha(erro) },
      ),
  });

  const enviar = () => {
    const faltando = {
      identificador: identificador.trim() === "",
      senha: senha === "",
    };
    setVazios(faltando);
    setFalha(null);
    if (!faltando.identificador && !faltando.senha) {
      entrar.mutate();
    }
  };

  return (
    <TelaDeAutenticacao segmentado={<SegmentadoDeAcesso atual="entrar" />}>
      <View style={styles.formulario}>
        <TextField
          label="RA ou e-mail"
          value={identificador}
          onChangeText={setIdentificador}
          autoCapitalize="none"
          autoCorrect={false}
          autoComplete="username"
          inputMode="email"
          returnKeyType="next"
          error={vazios.identificador ? "Informe o RA ou o e-mail." : undefined}
        />
        <View>
          <TextField
            label="Senha"
            password
            value={senha}
            onChangeText={setSenha}
            autoComplete="current-password"
            returnKeyType="go"
            onSubmitEditing={enviar}
            error={
              vazios.senha
                ? "Informe a senha."
                : falha?.campo === "senha"
                  ? falha.mensagem
                  : undefined
            }
          />
          <View style={styles.esqueci}>
            <TextLink
              label="Esqueci minha senha"
              onPress={() => router.push("/esqueci-senha")}
            />
          </View>
        </View>

        <Button
          label={entrar.isPending ? "Entrando..." : "Entrar"}
          size="large"
          disabled={entrar.isPending}
          onPress={enviar}
        />
        {falha?.campo === "formulario" && (
          <AvisoDeErro mensagem={falha.mensagem} />
        )}

        <Text style={[textStyles.corpo, styles.aviso, { color: colors.ink2 }]}>
          Primeiro acesso? Aluno cria a conta em Cadastrar. Professor define a
          senha em Esqueci minha senha.
        </Text>
      </View>
    </TelaDeAutenticacao>
  );
}

const styles = StyleSheet.create({
  formulario: { gap: 16 },
  esqueci: { alignItems: "flex-end" },
  aviso: { textAlign: "center", marginTop: 8 },
});

