// Captura o /login do compose local em 390 x 844 (escala 2) e monta ao lado da prancheta.
const fs = require("node:fs");
const path = require("node:path");
const raiz = "C:/Users/Guilherme Gimenes/Documents/Repos/tcc/maxx-engenheiro";
const { chromium } = require(
  require.resolve("@playwright/test", { paths: [path.join(raiz, "e2e")] }),
);
const saida = process.argv[2];

(async () => {
  const navegador = await chromium.launch();
  for (const [tema, esquema] of [
    ["claro", "light"],
    ["escuro", "dark"],
  ]) {
    const pagina = await navegador.newPage({
      viewport: { width: 390, height: 844 },
      deviceScaleFactor: 2,
      colorScheme: esquema,
      isMobile: true,
      hasTouch: true,
    });
    await pagina.goto("http://localhost/login");
    // Como na prancheta: RA digitado e a senha em foco, escondida.
    await pagina.getByLabel("RA ou e-mail").fill("2023001");
    const senha = pagina.getByLabel("Senha", { exact: true });
    await senha.fill("senha123456");
    await senha.focus();
    await pagina.waitForTimeout(400);
    const app = path.join(saida, `login-${tema}-app.png`);
    await pagina.screenshot({ path: app });
    await pagina.close();

    const lado = await navegador.newPage({
      viewport: { width: 780 * 2 + 48, height: 1688 + 64 },
    });
    const uri = (arquivo) =>
      `data:image/png;base64,${fs.readFileSync(arquivo).toString("base64")}`;
    await lado.setContent(`<body style="margin:0;background:#888;font:600 22px sans-serif;color:#fff">
      <div style="display:flex;gap:48px">
        <div><div style="height:64px;line-height:64px">Prancheta (${tema})</div>
          <img src="${uri(path.join(raiz, `design/telas/login-${tema}.png`))}" width="780" height="1688"></div>
        <div><div style="height:64px;line-height:64px">App (${tema})</div>
          <img src="${uri(app)}" width="780" height="1688"></div>
      </div></body>`);
    await lado.screenshot({ path: path.join(saida, `login-${tema}-lado-a-lado.png`) });
    await lado.close();
  }
  await navegador.close();
})();

