      .mockResolvedValueOnce(json(200, TERMO))
      .mockResolvedValueOnce(json(201, SESSAO));
    const { gerenciador } = await renderComApi(
      <ComDados dados={COMPLETO}>
        <TermoScreen />
      </ComDados>,
      api,
