  dados,
  children,
}: {
  dados: DadosDoCadastro | null;
  children: React.ReactNode;
}) {
  return (
    <CadastroProvider>
      <Semear dados={dados} />
      {children}
    </CadastroProvider>
  );
}

function Semear({ dados }: { dados: DadosDoCadastro | null }) {
  const { comecar } = useCadastro();
  useEffect(() => {
    if (dados) comecar(dados);
  }, [comecar, dados]);
  return null;
}

