// Captura os três passos do cadastro no compose local, em 390 x 844 (escala 2), claro e
// escuro, e monta o passo 1 ao lado da prancheta.
const fs = require("node:fs");
const path = require("node:path");
const { execFileSync } = require("node:child_process");
const raiz = "C:/Users/Guilherme Gimenes/Documents/Repos/tcc/maxx-engenheiro";
const { chromium } = require(
  require.resolve("@playwright/test", { paths: [path.join(raiz, "e2e")] }),
);
const saida = process.argv[2];

function elegivel(n) {
  const ra = `8${n}`;
  const email = `captura.${n}@al.unieduk.com.br`;
  execFileSync(
    "docker",
    [
      "compose",
      "exec",
      "-T",
      "postgres",
      "sh",
      "-c",
      'psql -q -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$POSTGRES_DB" -tA',
    ],
    {
      cwd: raiz,
      encoding: "utf8",
      input: `INSERT INTO cadastro_elegivel (id, papeis, ra, email, nome_completo, curso_id, semestre)
        SELECT gen_random_uuid(), 1, '${ra}', '${email}', 'Ana Paula Souza Lima', id, 3 FROM curso WHERE sigla = 'CC';`,
    },
  );
  return { ra, email };
}

const uri = (arquivo) =>
  `data:image/png;base64,${fs.readFileSync(arquivo).toString("base64")}`;

(async () => {
  const navegador = await chromium.launch();
  for (const [tema, esquema] of [
    ["claro", "light"],
    ["escuro", "dark"],
  ]) {
    const pagina = await navegador.newPage({
      viewport: { width: 390, height: 844 },
      deviceScaleFactor: 2,
      colorScheme: esquema,
      isMobile: true,
      hasTouch: true,
    });
    const foto = (nome) => path.join(saida, `cadastro-${nome}-${tema}.png`);

    // Passo 1, como na prancheta: RA digitado e o e-mail em foco, vazio.
    await pagina.goto("http://localhost/cadastro");
    await pagina.getByLabel("RA", { exact: true }).fill("2023001");
    await pagina.getByLabel("E-mail institucional").focus();
    await pagina.waitForTimeout(400);
    await pagina.screenshot({ path: foto("1-dados") });

    // Passos 2 e 3 com uma linha de verdade da base.
    const { ra, email } = elegivel(`${Date.now()}`.slice(-9));
    await pagina.getByLabel("RA", { exact: true }).fill(ra);
    await pagina.getByLabel("E-mail institucional").fill(email);
    await pagina.getByLabel("Crie uma senha").fill("senha-da-captura");
    await pagina.getByRole("button", { name: "Continuar" }).click();
    await pagina.getByText("2 de 3").waitFor();
    await pagina.getByLabel("Nome de exibição").fill("Ana Paula");
    await pagina.getByText("Está livre.").waitFor();
    await pagina.waitForTimeout(300);
    await pagina.screenshot({ path: foto("2-arroba") });

    await pagina.getByRole("button", { name: "Continuar" }).click();
    await pagina.getByRole("heading", { name: "Fotos" }).waitFor();
    await pagina.waitForTimeout(300);
    await pagina.screenshot({ path: foto("3-termo-topo") });
    await pagina
      .getByRole("button", { name: "Aceitar e criar conta" })
      .scrollIntoViewIfNeeded();
    await pagina.waitForTimeout(300);
    await pagina.screenshot({ path: foto("3-termo-fim") });
    await pagina.close();

    const lado = await navegador.newPage({
      viewport: { width: 780 * 2 + 48, height: 1688 + 64 },
    });
    await lado.setContent(`<body style="margin:0;background:#888;font:600 22px sans-serif;color:#fff">
      <div style="display:flex;gap:48px">
        <div><div style="height:64px;line-height:64px">Prancheta (${tema})</div>
          <img src="${uri(path.join(raiz, `design/telas/cadastro-${tema}.png`))}" width="780" height="1688"></div>
        <div><div style="height:64px;line-height:64px">App, passo 1 (${tema})</div>
          <img src="${uri(foto("1-dados"))}" width="780" height="1688"></div>
      </div></body>`);
    await lado.screenshot({
      path: path.join(saida, `cadastro-1-lado-a-lado-${tema}.png`),
    });
    await lado.close();

    // Passos 2 e 3 lado a lado, para revisar de uma vez.
    const tres = await navegador.newPage({
      viewport: { width: 780 * 3 + 96, height: 1688 + 64 },
    });
    await tres.setContent(`<body style="margin:0;background:#888;font:600 22px sans-serif;color:#fff">
      <div style="display:flex;gap:48px">
        ${["2-arroba", "3-termo-topo", "3-termo-fim"]
          .map(
            (nome) =>
              `<div><div style="height:64px;line-height:64px">${nome} (${tema})</div><img src="${uri(foto(nome))}" width="780" height="1688"></div>`,
          )
          .join("")}
      </div></body>`);
    await tres.screenshot({
      path: path.join(saida, `cadastro-2-e-3-${tema}.png`),
    });
    await tres.close();
  }
  await navegador.close();
})();

