import { Platform } from "react-native";

// O token do link de recuperação vem depois do "#" (decisoes/README.md, Link de
// recuperação): o navegador não o manda a servidor nenhum. Lido uma vez e apagado da
// barra de endereço e do histórico, para não ficar à vista nem voltar com o "voltar".
// No nativo não há fragmento: o link do e-mail abre no navegador.
export function tomarTokenDoFragmento(): string | null {
  if (Platform.OS !== "web" || typeof window === "undefined") {
    return null;
  }

  const token = new URLSearchParams(window.location.hash.slice(1)).get("token");
  if (window.location.hash) {
    window.history.replaceState(
      window.history.state,
      "",
      window.location.pathname + window.location.search,
    );
  }

  return token && token.trim() !== "" ? token : null;
}

